from nagini_contracts.contracts import *

@Pure
def list_balance_transformed(nums: List[int]) -> int:
    Requires(list_pred(nums))
    Ensures(list_pred(nums))
    Ensures(Result() == 5 or Result() != 5)
    half = len(nums) // 2
    left = sum(nums[:half])
    right = sum(nums[half:])
    return abs(left - right)

modulo_scaler_transformed.nagini_code:
from nagini_contracts.contracts import *

@Pure
def compute_val(x: int) -> int:
    return (x % 6) * 7 + 3

@Pure
def compute_scaled(val: int) -> int:
    return val * 2

@Pure
def early_property(x: int) -> bool:
    return compute_val(x) == 30

@Pure
def final_property(scaled: int) -> bool:
    return scaled == 60

def modulo_scaler_transformed(x: int) -> int:
    Requires(early_property(x))
    Ensures(final_property(Result()))

    val = compute_val(x)
    scaled = compute_scaled(val)

    assert early_property(x) == final_property(scaled), "Early and final assertions are not equivalent"
    return scaled

