from nagini_contracts.contracts import *

@Pure
def calculate_magnitude(real: float, imag: float) -> float:
    return (real**2 + imag**2)**0.5

@Pure
def process_complex_number_transformed(real: float, imag: float) -> int:
    Requires(True)  # No real preconditions as the inputs are floats
    Ensures(Result() == 10)
    Ensures(round(calculate_magnitude(real, imag)) == 10)
    magnitude = calculate_magnitude(real, imag)
    rounded_magnitude = round(magnitude)
    return rounded_magnitude

