from nagini_contracts.contracts import *

@Pure
def abs_value(x: int) -> int:
    Ensures(Result() == (x if x >= 0 else -x))
    return x if x >= 0 else -x

@Pure
def process_data_transformed(x: int) -> int:
    Requires(-50 <= x <= 50)
    Ensures(Result() >= 0)
    Ensures((x == 50) == (Result() == 100))
    y = x * 2
    z = abs_value(y)
    return z
